[CmdletBinding()]
param([Parameter(Mandatory)][string]$PlanCsv,[Parameter(Mandatory)][string]$StateDir,[Parameter(Mandatory)][string[]]$ApprovedRoots,[int]$StopAfterOperations=0)
$ErrorActionPreference='Stop';$here=Split-Path -Parent $MyInvocation.MyCommand.Path;New-Item -ItemType Directory -Path $StateDir -Force|Out-Null
$existingStageLog=Join-Path $StateDir 'staging.jsonl';$existingResultLog=Join-Path $StateDir 'results.jsonl';if((-not(Test-Path $existingStageLog))-and(-not(Test-Path $existingResultLog))){& (Join-Path $here 'Test-LocalFilePlan.ps1') -PlanCsv $PlanCsv -ApprovedRoots $ApprovedRoots|Out-Null}
$staging=Join-Path $StateDir 'staging';$duplicates=Join-Path $StateDir 'duplicate-isolation';$conflicts=Join-Path $StateDir 'conflict-isolation';New-Item -ItemType Directory -Path $staging,$duplicates,$conflicts -Force|Out-Null
$stageLog=Join-Path $StateDir 'staging.jsonl';$resultLog=Join-Path $StateDir 'results.jsonl';$progress=Join-Path $StateDir 'progress.json';$rows=@(Import-Csv -LiteralPath $PlanCsv);$ops=0
function Append([string]$p,[hashtable]$v){$v.time=(Get-Date).ToString('o');Add-Content -LiteralPath $p -Value ($v|ConvertTo-Json -Compress -Depth 5)-Encoding utf8}
function SaveProgress([string]$phase,[int]$done,[string]$current){$o=[ordered]@{phase=$phase;done=$done;total=$rows.Count;percent=if($rows.Count){[math]::Round(100*$done/$rows.Count,2)}else{0};current=$current;updatedAt=(Get-Date).ToString('o')};[IO.File]::WriteAllText($progress,($o|ConvertTo-Json),[Text.UTF8Encoding]::new($false))}
function Alt([string]$base,[string]$source,[string]$name){$id=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($source))).Substring(0,16);Join-Path $base ($id+'__'+$name)}
$done=[Collections.Generic.Dictionary[string,object]]::new([StringComparer]::OrdinalIgnoreCase);if(Test-Path $resultLog){foreach($line in [IO.File]::ReadLines($resultLog)){if($line){$r=$line|ConvertFrom-Json;$done[[string]$r.source]=$r}}};$staged=[Collections.Generic.Dictionary[string,object]]::new([StringComparer]::OrdinalIgnoreCase);if(Test-Path $stageLog){foreach($line in [IO.File]::ReadLines($stageLog)){if($line){$r=$line|ConvertFrom-Json;$staged[[string]$r.source]=$r}}}
SaveProgress 'staging' $done.Count ''
for($i=0;$i -lt $rows.Count;$i++){$r=$rows[$i];$s=[IO.Path]::GetFullPath($r.SourcePath);$t=[IO.Path]::GetFullPath($r.TargetPath);if($done.ContainsKey($s)){continue};if($s.Equals($t,[StringComparison]::OrdinalIgnoreCase)){Append $resultLog @{source=$s;target=$t;final=$s;status='already-in-place';bytes=[long]$r.SizeBytes};$done[$s]=$true;continue};if($staged.ContainsKey($s) -and (Test-Path -LiteralPath ([string]$staged[$s].stage))){continue};$sp=Join-Path $staging (('{0:D8}' -f $i)+[IO.Path]::GetExtension($s));[IO.File]::Move($s,$sp);Append $stageLog @{source=$s;target=$t;stage=$sp;bytes=[long]$r.SizeBytes};$staged[$s]=[pscustomobject]@{stage=$sp};$ops++;if(($i%250)-eq0){SaveProgress 'staging' $done.Count $s};if(($StopAfterOperations -gt 0) -and ($ops -ge $StopAfterOperations)){SaveProgress 'interrupted-for-test' $done.Count $s;return}}
foreach($r in $rows){$s=[IO.Path]::GetFullPath($r.SourcePath);$t=[IO.Path]::GetFullPath($r.TargetPath);if($done.ContainsKey($s)){continue};$sp=[string]$staged[$s].stage;if(-not(Test-Path -LiteralPath $sp)){throw "Missing staged file: $sp"};if(-not(Test-Path -LiteralPath $t -PathType Leaf)){New-Item -ItemType Directory -Path (Split-Path -Parent $t)-Force|Out-Null;[IO.File]::Move($sp,$t);$final=$t;$status='placed'}else{$same=([IO.FileInfo]::new($t).Length-eq[IO.FileInfo]::new($sp).Length)-and((Get-FileHash -LiteralPath $t -Algorithm SHA256).Hash-eq(Get-FileHash -LiteralPath $sp -Algorithm SHA256).Hash);if($same){$final=Alt $duplicates $s ([IO.Path]::GetFileName($s));[IO.File]::Move($sp,$final);$status='duplicate-isolated'}else{$final=Alt $conflicts $s ([IO.Path]::GetFileName($s));[IO.File]::Move($sp,$final);$status='conflict-isolated'}};Append $resultLog @{source=$s;target=$t;final=$final;status=$status;bytes=[long]$r.SizeBytes};$done[$s]=$true;$ops++;if(($done.Count%250)-eq0){SaveProgress 'placing' $done.Count $t};if($StopAfterOperations-gt0-and$ops-ge$StopAfterOperations){SaveProgress 'interrupted-for-test' $done.Count $s;return}}
SaveProgress 'complete' $done.Count '';[ordered]@{status='complete';terminal=$done.Count;total=$rows.Count;resultLog=$resultLog}|ConvertTo-Json
